'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var sameValue = require( '@stdlib/assert/is-same-value' );
var tryRequire = require( '@stdlib/utils/try-require' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var Float64Array = require( '@stdlib/array/float64' );
var main = require( './../lib/main.js' );
var fixtures = require( './fixtures/exact-prefixes.json' ).cases;
var addonPath = resolve( __dirname, './../src/addon.node' );
var nativePath = resolve( __dirname, './../lib/native.js' );
var addon = tryRequire( addonPath );
var calls = 0;
var native;

if ( !(addon instanceof Error) ) {
	require.cache[ addonPath ].exports = function instrument() {
		calls += 1;
		return addon.apply( null, arguments );
	};
	delete require.cache[ nativePath ];
}
native = tryRequire( nativePath );


// FUNCTIONS //

/**
* Returns a selected float64 view.
*
* @private
* @param {Float64Array} data - data
* @param {integer} N - length
* @param {integer} stride - stride
* @param {integer} offset - offset
* @returns {ndarray} view
*/
function vector( data, N, stride, offset ) {
	return new ndarray( 'float64', data, [ N ], [ stride ], offset, 'row-major' );
}

/**
* Compares all entries using exact SameValue semantics.
*
* @private
* @param {Float64Array} a - first buffer
* @param {Float64Array} b - second buffer
* @returns {boolean} whether every entry matches
*/
function equalBuffers( a, b ) {
	var i;
	if ( a.length !== b.length ) {
		return false;
	}
	for ( i = 0; i < a.length; i++ ) {
		if ( !sameValue( a[ i ], b[ i ] ) ) {
			return false;
		}
	}
	return true;
}

/**
* Returns a scalar selecting its own offset.
*
* @private
* @param {number} value - scalar
* @returns {Object} scalar view
*/
function scalar( value ) {
	return {
		'data': [ 123.0, value ],
		'offset': 1
	};
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof main, 'function', 'main export is a function' );
	t.end();
});

tape( 'compiled cumulative prefixes equal independently rounded exact sums', {
	'skip': native instanceof Error
}, function test( t ) {
	var expected;
	var strides;
	var initial;
	var actual;
	var before;
	var values;
	var output;
	var input;
	var count;
	var sx;
	var sy;
	var ox;
	var oy;
	var x;
	var y;
	var i;
	var j;
	var k;
	var q;

	count = calls;
	strides = [ -3, -1, 1, 2, 3 ];
	for ( i = 0; i < fixtures.length; i++ ) {
		values = fixtures[ i ].x;
		initial = scalar( fixtures[ i ].initial );
		for ( j = 0; j < strides.length; j++ ) {
			for ( k = 0; k < strides.length; k++ ) {
				sx = strides[ j ];
				sy = strides[ k ];
				ox = 3 + ( (sx < 0) ? -2*sx : 0 );
				oy = 3 + ( (sy < 0) ? -2*sy : 0 );
				input = new Float64Array( 32 ).subarray( 2, 25 );
				output = new Float64Array( 32 ).subarray( 3, 26 );
				input.fill( 999.0 );
				output.fill( 987.0 );
				expected = new Float64Array( output );
				for ( q = 0; q < 3; q++ ) {
					input[ ox+(q*sx) ] = values[ q ];
					expected[ oy+(q*sy) ] = fixtures[ i ].prefixes[ q ];
				}
				before = new Float64Array( input );
				x = vector( input, 3, sx, ox );
				y = vector( output, 3, sy, oy );
				actual = native( [ x, y, initial ] );
				t.strictEqual( actual, y, 'preserves output identity' );
				t.deepEqual( output, expected, 'exact mathematical prefixes and guards' );
				t.deepEqual( input, before, 'input and guards unchanged' );
			}
		}
	}
	t.strictEqual( calls-count, 750, '750 actual addon calls over independent layouts' );
	t.end();
});

tape( 'native sequential aliases, zero strides and special values preserve the adopted algorithm', {
	'skip': native instanceof Error
}, function test( t ) {
	var sequences;
	var expected;
	var strides;
	var initial;
	var actual;
	var sx;
	var sy;
	var ox;
	var oy;
	var i;
	var j;
	var k;
	var q;

	sequences = [ [ 1e16, 1.0, -1e16, 3.0 ], [ -0.0, -0.0, 0.0, -0.0 ], [ NaN, 1.0, Infinity, -Infinity ], [ Infinity, 0.0, -Infinity, 1.0 ] ];
	strides = [ -1, 0, 1, 2 ];
	initial = scalar( -0.0 );
	for ( i = 0; i < sequences.length; i++ ) {
		for ( j = 0; j < strides.length; j++ ) {
			for ( k = 0; k < strides.length; k++ ) {
				sx = strides[ j ];
				sy = strides[ k ];
				ox = 4 + ( (sx < 0) ? -3*sx : 0 );
				oy = 5 + ( (sy < 0) ? -3*sy : 0 );
				expected = new Float64Array( 20 );
				for ( q = 0; q < 4; q++ ) {
					expected[ ox+(q*sx) ] = sequences[ i ][ q ];
				}
				actual = new Float64Array( expected );
				main( [ vector( expected, 4, sx, ox ), vector( expected, 4, sy, oy ), initial ] );
				native( [ vector( actual, 4, sx, ox ), vector( actual, 4, sy, oy ), initial ] );
				t.strictEqual( equalBuffers( actual, expected ), true, 'whole shared buffer matches sequential JS including NaN/signedzero' );
			}
		}
	}
	t.end();
});

tape( 'snapshot, scalar extraction, fallback and post-increment width semantics', {
	'skip': native instanceof Error
}, function test( t ) {
	var count;
	var data;
	var init;
	var out;
	var x;
	var y;

	data = new Float64Array( [ 999.0, 2.0 ] );
	out = new Float64Array( [ 999.0, 0.0 ] );
	x = vector( data, 1, 2147483647, 1 );
	y = vector( out, 1, 1, 1 );
	count = calls;
	t.strictEqual( native( [ x, y, scalar( 3.0 ) ] ), y, 'wide singleton returns same output' );
	t.strictEqual( out[ 1 ], 5.0, 'wider valid JS result preserved' );
	t.strictEqual( calls, count, 'unused post-increment overflow falls back' );
	data = [ 1e16, 1.0, -1e16 ];
	out = [ 0.0, 0.0, 0.0 ];
	x = {
		'data': data,
		'shape': [ 3 ],
		'strides': [ 1 ],
		'offset': 0
	};
	y = {
		'data': out,
		'shape': [ 3 ],
		'strides': [ 1 ],
		'offset': 0
	};
	t.strictEqual( native( [ x, y, scalar( 0.0 ) ] ), y, 'ordinary accepted arrays fall back' );
	t.deepEqual( out, [ 1e16, 1e16, 1.0 ], 'fallback retains compensation' );
	t.strictEqual( calls, count, 'fallback does not invoke addon' );
	x = vector( new Float64Array( 0 ), 0, 1, 0 );
	y = vector( new Float64Array( [ 42.0 ] ), 1, 1, 0 );
	init = {
		'data': null,
		'offset': 0
	};
	t.throws( function invalidScalar() {
		native( [ x, y, init ] );
	}, 'empty input still extracts scalar' );
	t.deepEqual( y.data, new Float64Array( [ 42.0 ] ), 'empty failing scalar leaves output untouched' );
	t.strictEqual( native( [ x, y, scalar( 2.0 ) ] ), y, 'empty valid scalar returns output' );
	t.strictEqual( calls, count, 'empty uses original fallback' );
	t.end();
});
